@font-face {
  font-family: "Open Sans";
  src: local("OpenSans-Light"), url("../fonts/OpenSans-Light.woff2") format("woff2");
  font-weight: 300;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Open Sans";
  src: local("OpenSans-Light-Italic"), url("../fonts/OpenSans-Light-Italic.woff2") format("woff2");
  font-weight: 300;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "Open Sans";
  src: local("OpenSans-Bold"), url("../fonts/OpenSans-Bold.woff2") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Open Sans";
  src: local("OpenSans-Bold-Italic"), url("../fonts/OpenSans-Bold-Italic.woff2") format("woff2");
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}

/* Подключите шрифт Open Sans с начертаниями: Light, Light Italic, Bold и Bold Italic  */

body {
  margin: 0;
  font-weight: 300;
  font-size: 18px;
  text-size-adjust: 100%;
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
}

.hero__image {
  display: block;
  background-image: url(../images/hero.jpg);
  background-repeat: no-repeat;
  background-position: center bottom;
  background-size: cover;
  aspect-ratio: 1.5 / 1;
}

.hero__content {
  display: grid;
  gap: 15px;
  border-block-end: 1px solid #000;
  padding: 50px;
}

.quote {
  margin: 0;
}

.quote__text {
  margin: 0;
  font-weight: 700;
  font-size: 45px;
  text-transform: uppercase;
}

.quote__author {
  margin: 0;
}

.quote__author cite {
  font-style: normal;
}

.cards {
  padding: 50px;
}

.cards__header {
  margin: 0;
  font-size: 38px;
  font-style: italic;
  text-transform: uppercase;
}

.cards__list {
  margin-block-start: 50px;
  margin-block-end: 0;
  padding-inline-start: 0;
  list-style-type: none;
}

.cards__item:not(:first-child) {
  margin-block-start: 50px;
}

.card_type_reverse {
  flex-direction: row-reverse;
}

.card__image {
  display: block;
  max-inline-size: 100%;
  object-fit: cover;
}

.card__content {
  border: 1px solid #000;
  padding: 25px;
  color: #fff;
  background-color: #000;
}

.card__title {
  max-inline-size: 25ch;
  margin: 0;
  font-size: 31px;
  font-style: italic;
  text-transform: uppercase;
}

.card__text {
  margin-block-start: 20px;
}

.card__paragraph {
  margin: 0;
}

.card__paragraph:not(:first-child) {
  margin-block-start: 10px;
}

.footer {
  border-block-start: 1px solid #000;
  padding: 50px;
}

.footer__copy {
  margin: 0;
  font-style: italic;
  text-align: end;
}

@supports (font-variation-settings: normal) {
  @keyframes heading-rotate {
    from {
    }

    to {
    }
  }

  body {
  }

  .quote__text {
    animation: heading-rotate 3s linear alternate infinite;
  }

  .cards__header,
  .card__title,
  .footer__copy {
  }

  .cards__header {
  }

  .card__title {
  }

  .footer__copy {
  }
}

@media (width >= 768px) {
  .hero {
    display: flex;
    min-block-size: 100dvb;
  }

  .hero__image {
    inline-size: 50%;
  }

  .hero__content {
    grid-template-rows: 1fr auto;
    box-sizing: border-box;
    inline-size: 50%;
  }

  .hero__quote {
    align-self: center;
    box-sizing: border-box;
  }

  .quote__text {
    max-inline-size: 20ch;
  }

  .card {
    display: flex;
  }

  .card__image {
    inline-size: 50%;
    aspect-ratio: 2 / 1;
  }

  .card__content {
    display: grid;
    flex-grow: 1;
    grid-template-rows: 1fr auto;
  }

  .card__title {
    align-self: center;
  }
}
